-- DOST-IskoLens MySQL schema (generated by `flask export-schema`)
-- Operational modules only; analytics tables will be added once the DOST dataset is received.

SET NAMES utf8mb4;

CREATE TABLE municipalities (
	id INTEGER NOT NULL AUTO_INCREMENT, 
	name VARCHAR(80) NOT NULL, 
	psgc_code VARCHAR(12), 
	is_capital BOOL NOT NULL, 
	CONSTRAINT pk_municipalities PRIMARY KEY (id), 
	CONSTRAINT uq_municipalities_name UNIQUE (name), 
	CONSTRAINT uq_municipalities_psgc_code UNIQUE (psgc_code)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


CREATE TABLE scholarship_cycles (
	id INTEGER NOT NULL AUTO_INCREMENT, 
	label VARCHAR(20) NOT NULL, 
	start_year INTEGER NOT NULL, 
	is_active BOOL NOT NULL DEFAULT '1', 
	CONSTRAINT pk_scholarship_cycles PRIMARY KEY (id), 
	CONSTRAINT uq_scholarship_cycles_label UNIQUE (label)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


CREATE TABLE scholarship_programs (
	id INTEGER NOT NULL AUTO_INCREMENT, 
	name VARCHAR(60) NOT NULL, 
	is_active BOOL NOT NULL, 
	CONSTRAINT pk_scholarship_programs PRIMARY KEY (id), 
	CONSTRAINT uq_scholarship_programs_name UNIQUE (name)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


CREATE TABLE heis (
	id INTEGER NOT NULL AUTO_INCREMENT, 
	name VARCHAR(160) NOT NULL, 
	municipality_id INTEGER, 
	is_active BOOL NOT NULL, 
	CONSTRAINT pk_heis PRIMARY KEY (id), 
	CONSTRAINT uq_heis_name UNIQUE (name), 
	CONSTRAINT fk_heis_municipality_id_municipalities FOREIGN KEY(municipality_id) REFERENCES municipalities (id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


CREATE TABLE secondary_schools (
	id INTEGER NOT NULL AUTO_INCREMENT, 
	name VARCHAR(160) NOT NULL, 
	municipality_id INTEGER NOT NULL, 
	is_active BOOL NOT NULL, 
	CONSTRAINT pk_secondary_schools PRIMARY KEY (id), 
	CONSTRAINT uq_secondary_schools_name_municipality UNIQUE (name, municipality_id), 
	CONSTRAINT fk_secondary_schools_municipality_id_municipalities FOREIGN KEY(municipality_id) REFERENCES municipalities (id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE INDEX ix_secondary_schools_municipality_id ON secondary_schools (municipality_id);

CREATE TABLE users (
	id INTEGER NOT NULL AUTO_INCREMENT, 
	first_name VARCHAR(80) NOT NULL, 
	last_name VARCHAR(80) NOT NULL, 
	email VARCHAR(160) NOT NULL, 
	username VARCHAR(40) NOT NULL, 
	password_hash VARCHAR(100), 
	`role` VARCHAR(20) NOT NULL, 
	status VARCHAR(20) NOT NULL, 
	contact_number VARCHAR(20), 
	office VARCHAR(160), 
	failed_login_attempts INTEGER NOT NULL, 
	is_locked BOOL NOT NULL, 
	locked_at DATETIME, 
	last_login_at DATETIME, 
	password_changed_at DATETIME, 
	privacy_consent_at DATETIME, 
	approved_by_id INTEGER, 
	approved_at DATETIME, 
	signup_status_token VARCHAR(64), 
	pref_font_size VARCHAR(10) NOT NULL, 
	pref_theme VARCHAR(10) NOT NULL DEFAULT 'light', 
	pref_default_municipality_id INTEGER, 
	pref_export_format VARCHAR(10) NOT NULL, 
	pref_email_high_risk BOOL NOT NULL, 
	pref_weekly_digest BOOL NOT NULL, 
	created_at DATETIME NOT NULL, 
	updated_at DATETIME NOT NULL, 
	CONSTRAINT pk_users PRIMARY KEY (id), 
	CONSTRAINT uq_users_email UNIQUE (email), 
	CONSTRAINT uq_users_username UNIQUE (username), 
	CONSTRAINT fk_users_approved_by_id_users FOREIGN KEY(approved_by_id) REFERENCES users (id), 
	CONSTRAINT uq_users_signup_status_token UNIQUE (signup_status_token), 
	CONSTRAINT fk_users_pref_default_municipality_id_municipalities FOREIGN KEY(pref_default_municipality_id) REFERENCES municipalities (id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


CREATE TABLE audit_logs (
	id INTEGER NOT NULL AUTO_INCREMENT, 
	created_at DATETIME NOT NULL, 
	user_id INTEGER, 
	username VARCHAR(80), 
	category VARCHAR(15) NOT NULL, 
	action VARCHAR(80) NOT NULL, 
	target_type VARCHAR(30), 
	target_id VARCHAR(40), 
	target_label VARCHAR(200), 
	details_json TEXT, 
	ip_address VARCHAR(45), 
	prev_hash VARCHAR(64) NOT NULL, 
	entry_hash VARCHAR(64) NOT NULL, 
	CONSTRAINT pk_audit_logs PRIMARY KEY (id), 
	CONSTRAINT fk_audit_logs_user_id_users FOREIGN KEY(user_id) REFERENCES users (id), 
	CONSTRAINT uq_audit_logs_entry_hash UNIQUE (entry_hash)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE INDEX ix_audit_logs_category ON audit_logs (category);
CREATE INDEX ix_audit_logs_created_at ON audit_logs (created_at);

CREATE TABLE import_batches (
	id INTEGER NOT NULL AUTO_INCREMENT, 
	filename VARCHAR(255) NOT NULL, 
	uploaded_by_id INTEGER NOT NULL, 
	uploaded_at DATETIME NOT NULL, 
	total_rows INTEGER NOT NULL, 
	valid_rows INTEGER NOT NULL, 
	error_rows INTEGER NOT NULL, 
	status VARCHAR(15) NOT NULL, 
	kind VARCHAR(15) NOT NULL DEFAULT 'scholars', 
	errors_json TEXT, 
	payload_json TEXT, 
	committed_at DATETIME, 
	CONSTRAINT pk_import_batches PRIMARY KEY (id), 
	CONSTRAINT fk_import_batches_uploaded_by_id_users FOREIGN KEY(uploaded_by_id) REFERENCES users (id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


CREATE TABLE notifications (
	id INTEGER NOT NULL AUTO_INCREMENT, 
	user_id INTEGER NOT NULL, 
	kind VARCHAR(30) NOT NULL, 
	title VARCHAR(200) NOT NULL, 
	body VARCHAR(300), 
	link VARCHAR(200), 
	urgency VARCHAR(10) NOT NULL, 
	is_read BOOL NOT NULL, 
	created_at DATETIME NOT NULL, 
	CONSTRAINT pk_notifications PRIMARY KEY (id), 
	CONSTRAINT fk_notifications_user_id_users FOREIGN KEY(user_id) REFERENCES users (id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE INDEX ix_notifications_user_id ON notifications (user_id);
CREATE INDEX ix_notifications_is_read ON notifications (is_read);

CREATE TABLE password_tokens (
	id INTEGER NOT NULL AUTO_INCREMENT, 
	user_id INTEGER NOT NULL, 
	token_hash VARCHAR(64) NOT NULL, 
	purpose VARCHAR(10) NOT NULL, 
	expires_at DATETIME NOT NULL, 
	used_at DATETIME, 
	created_at DATETIME NOT NULL, 
	CONSTRAINT pk_password_tokens PRIMARY KEY (id), 
	CONSTRAINT fk_password_tokens_user_id_users FOREIGN KEY(user_id) REFERENCES users (id), 
	CONSTRAINT uq_password_tokens_token_hash UNIQUE (token_hash)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE INDEX ix_password_tokens_user_id ON password_tokens (user_id);

CREATE TABLE user_sessions (
	id VARCHAR(64) NOT NULL, 
	user_id INTEGER NOT NULL, 
	created_at DATETIME NOT NULL, 
	last_seen_at DATETIME NOT NULL, 
	ip_address VARCHAR(45), 
	user_agent VARCHAR(255), 
	revoked_at DATETIME, 
	revoke_reason VARCHAR(40), 
	CONSTRAINT pk_user_sessions PRIMARY KEY (id), 
	CONSTRAINT fk_user_sessions_user_id_users FOREIGN KEY(user_id) REFERENCES users (id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE INDEX ix_user_sessions_user_id ON user_sessions (user_id);

CREATE TABLE scholars (
	id INTEGER NOT NULL AUTO_INCREMENT, 
	scholar_code VARCHAR(20) NOT NULL, 
	last_name VARCHAR(80) NOT NULL, 
	first_name VARCHAR(80) NOT NULL, 
	middle_name VARCHAR(80), 
	gender VARCHAR(10) NOT NULL, 
	birth_date DATE NOT NULL, 
	mobile_number VARCHAR(20) NOT NULL, 
	email VARCHAR(160), 
	program_id INTEGER NOT NULL, 
	cycle_id INTEGER NOT NULL, 
	municipality_id INTEGER NOT NULL, 
	secondary_school_id INTEGER NOT NULL, 
	enrollment_date DATE NOT NULL, 
	hei_id INTEGER NOT NULL, 
	degree_program VARCHAR(150) NOT NULL, 
	year_level SMALLINT NOT NULL, 
	status VARCHAR(25) NOT NULL, 
	academic_standing VARCHAR(20), 
	is_deactivated BOOL NOT NULL, 
	is_anonymized BOOL NOT NULL DEFAULT '0', 
	anonymized_at DATETIME, 
	deactivated_at DATETIME, 
	deactivated_by_id INTEGER, 
	created_by_id INTEGER, 
	updated_by_id INTEGER, 
	import_batch_id INTEGER, 
	created_at DATETIME NOT NULL, 
	updated_at DATETIME NOT NULL, 
	CONSTRAINT pk_scholars PRIMARY KEY (id), 
	CONSTRAINT uq_scholars_scholar_code UNIQUE (scholar_code), 
	CONSTRAINT fk_scholars_program_id_scholarship_programs FOREIGN KEY(program_id) REFERENCES scholarship_programs (id), 
	CONSTRAINT fk_scholars_cycle_id_scholarship_cycles FOREIGN KEY(cycle_id) REFERENCES scholarship_cycles (id), 
	CONSTRAINT fk_scholars_municipality_id_municipalities FOREIGN KEY(municipality_id) REFERENCES municipalities (id), 
	CONSTRAINT fk_scholars_secondary_school_id_secondary_schools FOREIGN KEY(secondary_school_id) REFERENCES secondary_schools (id), 
	CONSTRAINT fk_scholars_hei_id_heis FOREIGN KEY(hei_id) REFERENCES heis (id), 
	CONSTRAINT fk_scholars_deactivated_by_id_users FOREIGN KEY(deactivated_by_id) REFERENCES users (id), 
	CONSTRAINT fk_scholars_created_by_id_users FOREIGN KEY(created_by_id) REFERENCES users (id), 
	CONSTRAINT fk_scholars_updated_by_id_users FOREIGN KEY(updated_by_id) REFERENCES users (id), 
	CONSTRAINT fk_scholars_import_batch_id_import_batches FOREIGN KEY(import_batch_id) REFERENCES import_batches (id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE INDEX ix_scholars_hei_id ON scholars (hei_id);
CREATE INDEX ix_scholars_is_deactivated ON scholars (is_deactivated);
CREATE INDEX ix_scholars_municipality_id ON scholars (municipality_id);
CREATE INDEX ix_scholars_name_dob ON scholars (last_name, first_name, birth_date);
CREATE INDEX ix_scholars_cycle_id ON scholars (cycle_id);
CREATE INDEX ix_scholars_program_id ON scholars (program_id);
CREATE INDEX ix_scholars_status ON scholars (status);

CREATE TABLE academic_records (
	id INTEGER NOT NULL AUTO_INCREMENT, 
	scholar_id INTEGER NOT NULL, 
	academic_year VARCHAR(20) NOT NULL, 
	semester VARCHAR(20) NOT NULL, 
	semester_order SMALLINT NOT NULL, 
	gwa NUMERIC(5, 2) NOT NULL, 
	gwa_scale VARCHAR(10) NOT NULL, 
	year_level_at_record SMALLINT NOT NULL, 
	standing VARCHAR(20) NOT NULL, 
	date_recorded DATE NOT NULL, 
	encoded_by_id INTEGER, 
	created_at DATETIME NOT NULL, 
	CONSTRAINT pk_academic_records PRIMARY KEY (id), 
	CONSTRAINT uq_academic_records_scholar_term UNIQUE (scholar_id, academic_year, semester), 
	CONSTRAINT fk_academic_records_scholar_id_scholars FOREIGN KEY(scholar_id) REFERENCES scholars (id), 
	CONSTRAINT fk_academic_records_encoded_by_id_users FOREIGN KEY(encoded_by_id) REFERENCES users (id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE INDEX ix_academic_records_scholar_id ON academic_records (scholar_id);

CREATE TABLE graduation_records (
	id INTEGER NOT NULL AUTO_INCREMENT, 
	scholar_id INTEGER NOT NULL, 
	expected_graduation DATE, 
	actual_graduation DATE, 
	status VARCHAR(20) NOT NULL, 
	delay_reason VARCHAR(255), 
	updated_by_id INTEGER, 
	updated_at DATETIME NOT NULL, 
	CONSTRAINT pk_graduation_records PRIMARY KEY (id), 
	CONSTRAINT uq_graduation_records_scholar_id UNIQUE (scholar_id), 
	CONSTRAINT fk_graduation_records_scholar_id_scholars FOREIGN KEY(scholar_id) REFERENCES scholars (id), 
	CONSTRAINT fk_graduation_records_updated_by_id_users FOREIGN KEY(updated_by_id) REFERENCES users (id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


CREATE TABLE stipend_disbursements (
	id INTEGER NOT NULL AUTO_INCREMENT, 
	scholar_id INTEGER NOT NULL, 
	period VARCHAR(60) NOT NULL, 
	amount NUMERIC(12, 2) NOT NULL, 
	status VARCHAR(15) NOT NULL, 
	date_released DATE, 
	remarks VARCHAR(255), 
	encoded_by_id INTEGER, 
	created_at DATETIME NOT NULL, 
	updated_at DATETIME NOT NULL, 
	CONSTRAINT pk_stipend_disbursements PRIMARY KEY (id), 
	CONSTRAINT fk_stipend_disbursements_scholar_id_scholars FOREIGN KEY(scholar_id) REFERENCES scholars (id), 
	CONSTRAINT fk_stipend_disbursements_encoded_by_id_users FOREIGN KEY(encoded_by_id) REFERENCES users (id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE INDEX ix_stipend_disbursements_scholar_id ON stipend_disbursements (scholar_id);

CREATE TABLE termination_requests (
	id INTEGER NOT NULL AUTO_INCREMENT, 
	scholar_id INTEGER NOT NULL, 
	grounds VARCHAR(160) NOT NULL, 
	notes TEXT NOT NULL, 
	proposed_effective_date DATE NOT NULL, 
	status VARCHAR(15) NOT NULL, 
	requested_by_id INTEGER NOT NULL, 
	requested_at DATETIME NOT NULL, 
	reviewed_by_id INTEGER, 
	reviewed_at DATETIME, 
	review_remarks TEXT, 
	withdrawn_at DATETIME, 
	withdrawal_reason TEXT, 
	reversed_at DATETIME, 
	reversed_by_id INTEGER, 
	reversal_remarks TEXT, 
	CONSTRAINT pk_termination_requests PRIMARY KEY (id), 
	CONSTRAINT fk_termination_requests_scholar_id_scholars FOREIGN KEY(scholar_id) REFERENCES scholars (id), 
	CONSTRAINT fk_termination_requests_requested_by_id_users FOREIGN KEY(requested_by_id) REFERENCES users (id), 
	CONSTRAINT fk_termination_requests_reviewed_by_id_users FOREIGN KEY(reviewed_by_id) REFERENCES users (id), 
	CONSTRAINT fk_termination_requests_reversed_by_id_users FOREIGN KEY(reversed_by_id) REFERENCES users (id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE INDEX ix_termination_requests_status ON termination_requests (status);
CREATE INDEX ix_termination_requests_scholar_id ON termination_requests (scholar_id);

CREATE TABLE scholar_documents (
	id INTEGER NOT NULL AUTO_INCREMENT, 
	scholar_id INTEGER NOT NULL, 
	termination_request_id INTEGER, 
	doc_type VARCHAR(40) NOT NULL, 
	description VARCHAR(255), 
	original_filename VARCHAR(255) NOT NULL, 
	stored_name VARCHAR(80) NOT NULL, 
	mime_type VARCHAR(60) NOT NULL, 
	size_bytes INTEGER NOT NULL, 
	sha256 VARCHAR(64) NOT NULL, 
	uploaded_by_id INTEGER NOT NULL, 
	uploaded_at DATETIME NOT NULL, 
	is_deleted BOOL NOT NULL, 
	deleted_at DATETIME, 
	deleted_by_id INTEGER, 
	delete_reason VARCHAR(255), 
	CONSTRAINT pk_scholar_documents PRIMARY KEY (id), 
	CONSTRAINT fk_scholar_documents_scholar_id_scholars FOREIGN KEY(scholar_id) REFERENCES scholars (id), 
	CONSTRAINT fk_scholar_documents_termination_request_id_termination_requests FOREIGN KEY(termination_request_id) REFERENCES termination_requests (id), 
	CONSTRAINT uq_scholar_documents_stored_name UNIQUE (stored_name), 
	CONSTRAINT fk_scholar_documents_uploaded_by_id_users FOREIGN KEY(uploaded_by_id) REFERENCES users (id), 
	CONSTRAINT fk_scholar_documents_deleted_by_id_users FOREIGN KEY(deleted_by_id) REFERENCES users (id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE INDEX ix_scholar_documents_scholar_id ON scholar_documents (scholar_id);

-- Tamper protection: the audit log is append-only.
DELIMITER $$
CREATE TRIGGER audit_logs_no_update BEFORE UPDATE ON audit_logs FOR EACH ROW
BEGIN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'audit_logs is append-only'; END$$
CREATE TRIGGER audit_logs_no_delete BEFORE DELETE ON audit_logs FOR EACH ROW
BEGIN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'audit_logs is append-only'; END$$
DELIMITER ;
